import{z as s,x as i,o as A,c as o,q as l,j as t,D as E,d as e,s as C,S as r,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"跨数据中心训练","description":"","frontmatter":{"title":"跨数据中心训练","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-cross-dc.md","filePath":"llm/dist-cross-dc.md","lastUpdated":1791063341000}'),n={name:"llm/dist-cross-dc.md"};function d(p,a,h,m,c,u){const D=i("Mermaid");return A(),o("div",null,[a[2]||(a[2]=l('<h1 id="跨数据中心训练" tabindex="-1">跨数据中心训练 <a class="header-anchor" href="#跨数据中心训练" aria-label="Permalink to &quot;跨数据中心训练&quot;">​</a></h1><div class="epigraph"><p>同步 SGD 假设带宽免费；跨数据中心的墙上，一步全局归约的账单比一步计算贵出几个量级。</p><footer>—— 据 McMahan 等 2017 与 Douillard 等 2023 整理</footer></div><p><a href="/llm/dist-heterogeneous-parallel">上一课</a>在集群内部按能力配比；跨数据中心时，「集群内部」这个前提本身没了：数据中心之间的广域带宽通常比 DC 内低一到两个数量级，延迟高两个量级以上，且常按字节计费。本课写跨 DC 训练：什么动机值得付这笔钱，通信结构要怎么改，代价是什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把同步 SGD 原样搬到广域上，每步的全局归约段支配 step time：跨 DC 段的延迟与带宽让所有重叠技巧失效，因为归约本身就是被等待的消费方。</p><p><span class="marginnote">全局归约（all-reduce）就是把所有卡各自手里的梯度相加，再让每张卡都拿到同一份总和的通信操作。跨 DC 时这一步要走广域网，正是整个训练里最贵的一段。</span>但真实动机常常不是「网不够快」：单个 DC 租不满整机柜、想合并两地的空闲算力、或为容灾把训练摊在两地。动机不同，答案不同——这正是本课要先分类的原因。混淆动机的典型错误：为容灾把训练摊开，却继续做每步同步，结果吞吐掉一个量级，容灾也没得到（训练在一个 DC 掉线时照样全局停摆）。</p><h3 id="三种结构" tabindex="-1">三种结构 <a class="header-anchor" href="#三种结构" aria-label="Permalink to &quot;三种结构&quot;">​</a></h3><p>按通信频率从高到低排。第一种，分区放置：训练逻辑上仍是一个同步作业，但放置时把高频通信（TP、PP 段间）全部锁进 DC 内，跨 DC 只承担 DP 归约中能层次化、能稀疏化的部分——DC 内先归约，跨 DC 走每 DC 一份的体积。这是改动最小的一种，也只在跨 DC 带宽不太差时可行。第二种，局部更新：每个 DC 内跑多步局部 SGD，隔一段外层步才跨 DC 平均一次参数；联邦平均与 DiLoCo 是这条线的两个锚点，差别在局部步数与传输的 delta 形态（低秩、稀疏或量化压缩）。第三种，异步聚合：参数服务器或去中心化的周期性平均，彻底放弃同步语义，用陈旧梯度换带宽。</p><p><span class="marginnote">局部 \\(H\\) 步再平均，等价于外层步作用在 \\(H\\) 步梯度的加权组合上；局部步数越大越省通信，但外层步的「真实方向」偏差随 \\(H\\) 与各 DC 数据异构度涨。\\(H\\) 是用收敛税买带宽的汇率，不是免费旋钮。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型的决策序：先问动机。若只是想要更多卡，先算一笔账——跨 DC 归约的每字节成本加吞吐损失，对比「再租半个 DC」的差价，多数时候后者赢；若确要跨 DC（算力只在两地、或容灾硬需求），按带宽预算选结构：带宽尚可走分区放置，带宽紧张走局部更新，两地长期不稳走异步聚合。局部更新路线要定三件事：局部步数 \\(H\\)、传输的 delta 形态、以及聚合时的权重（按各 DC 的 token 量加权，不按台数）。容灾诉求单独处理：检查点跨 DC 异步复制（口径同检查点课），掉线方退出后其余 DC 走降级步，而不是全组等待。</p>',11)),(A(),t(r,null,{default:E(()=>[C(D,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOTIVE%7B%22%E8%B7%A8%20DC%20%E7%9A%84%E5%8A%A8%E6%9C%BA%3F%22%7D%20--%3E%7C%E5%8F%AA%E6%98%AF%E8%A6%81%E6%9B%B4%E5%A4%9A%E5%8D%A1%7C%20COST%5B%22%E5%85%88%E7%AE%97%E8%B4%A6%3A%20%E5%BD%92%E7%BA%A6%E6%88%90%E6%9C%AC%E5%AF%B9%E6%AF%94%E5%86%8D%E7%A7%9F%20DC%22%5D%0A%20%20MOTIVE%20--%3E%7C%E7%AE%97%E5%8A%9B%E5%8F%AA%E5%9C%A8%E4%B8%A4%E5%9C%B0%7C%20BW%7B%22%E8%B7%A8%20DC%20%E5%B8%A6%E5%AE%BD%3F%22%7D%0A%20%20MOTIVE%20--%3E%7C%E5%AE%B9%E7%81%BE%7C%20CKPT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E5%BC%82%E6%AD%A5%E5%A4%8D%E5%88%B6%20%2B%20%E9%99%8D%E7%BA%A7%E6%AD%A5%22%5D%0A%20%20BW%20--%3E%7C%E5%B0%9A%E5%8F%AF%7C%20PART%5B%22%E5%88%86%E5%8C%BA%E6%94%BE%E7%BD%AE%3A%20%E9%AB%98%E9%A2%91%E9%80%9A%E4%BF%A1%E9%94%81%E8%BF%9B%20DC%20%E5%86%85%22%5D%0A%20%20BW%20--%3E%7C%E7%B4%A7%E5%BC%A0%7C%20LOCAL%5B%22%E5%B1%80%E9%83%A8%20H%20%E6%AD%A5%20%2B%20%E5%8E%8B%E7%BC%A9%20delta%20%2B%20%E5%8A%A0%E6%9D%83%E5%B9%B3%E5%9D%87%22%5D%0A%20%20BW%20--%3E%7C%E9%95%BF%E6%9C%9F%E4%B8%8D%E7%A8%B3%7C%20ASYNC%5B%22%E5%BC%82%E6%AD%A5%E8%81%9A%E5%90%88%2C%20%E6%8E%A5%E5%8F%97%E9%99%88%E6%97%A7%E5%BA%A6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"用 \\(\\alpha\\)-\\(\\beta\\) 模型读 WAN：延迟项 \\(\\alpha\\) 是几十毫秒量级，任何「多次小交换」的结构在广域上都被延迟项杀死，所以跨 DC 结构一律要求「大而少」的交换——层次化到每 DC 一份、外层步拉长、delta 压缩，都是在把交换变大变少。局部更新的收敛税来自两处：局部方向的漂移（各 DC 数据分布不同则更疼）与外层步的等效学习率偏移，补偿手段是把外层步的学习率与聚合权重一起调，并用小规模两地实验标定 \\(H\\)。异步聚合把税变成陈旧度：参数版本差随网络抖动漂，动量与归一化统计对陈旧度的敏感度比同步 SGD 高，监控要盯版本差分布而不是平均吞吐。",-1)),(A(),t(r,null,{default:E(()=>[C(D,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20DCA%5B%22DC%20A%22%5D%0A%20%20%20%20A1%5B%22%E5%8D%A1%201%20%E7%9A%84%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20R1%5B%22DC%20%E5%86%85%E5%85%88%E5%BD%92%E7%BA%A6%22%5D%0A%20%20%20%20A2%5B%22%E5%8D%A1%202%20%E7%9A%84%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20R1%0A%20%20end%0A%20%20subgraph%20DCB%5B%22DC%20B%22%5D%0A%20%20%20%20B1%5B%22%E5%8D%A1%201%20%E7%9A%84%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20R2%5B%22DC%20%E5%86%85%E5%85%88%E5%BD%92%E7%BA%A6%22%5D%0A%20%20%20%20B2%5B%22%E5%8D%A1%202%20%E7%9A%84%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20R2%0A%20%20end%0A%20%20R1%20--%3E%7C%22%E6%AF%8F%20DC%20%E5%8F%AA%E4%BC%A0%E4%B8%80%E4%BB%BD%2C%20%E8%B5%B0%E5%B9%BF%E5%9F%9F%22%7C%20AVG%5B%22%E8%B7%A8%20DC%20%E5%B9%B3%E5%9D%87%22%5D%0A%20%20R2%20--%3E%20AVG%0A%20%20AVG%20--%3E%20BK1%5B%22%E7%BB%93%E6%9E%9C%E5%B9%BF%E6%92%AD%E5%9B%9E%20DC%20A%22%5D%0A%20%20AVG%20--%3E%20BK2%5B%22%E7%BB%93%E6%9E%9C%E5%B9%BF%E6%92%AD%E5%9B%9E%20DC%20B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">拿 7B 模型算笔账：梯度按 fp16 存约 14 GB。若每个 DC 里的 8 张卡各自直接跨广域交换，量级冲到上百 GB；层次化成「DC 内先归约、每 DC 只传一份」后，跨广域每步只走这 14 GB。</span></p><p><span class="marginnote">初学者容易以为异步聚合只是「慢一点的同步」，实际上它改写了优化问题本身：聚合进来的梯度可能是几步之前的旧版本，动量与归一化统计都会被陈旧度带偏，所以监控要盯「参数版本差的分布」，而不是平均吞吐。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写联邦学习的隐私协议与非 IID 统计理论，那是另一门课的域；也不给任何「某公司跨 DC 训练了 X 万卡」的具体数字——公开可考的大规模预训练仍以单 DC 为主，跨 DC 同步训练是前沿而非默认配置。分区放置的 DC 内映射按上一课处理；跨 DC 的检查点与丢失窗口口径归容错课。判定收尾：跨 DC 训练值得做，只在「动机成立且结构选对」同时满足时成立。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跨 DC 的墙是带宽与延迟的量级差；先问动机，再选结构，不混淆容灾与扩容。</li><li>三种结构：分区放置（高频通信锁 DC 内）、局部更新（\\(H\\) 步加压缩 delta）、异步聚合（放弃同步语义）。</li><li>广域上交换要大而少：层次化到每 DC 一份、外层步拉长都是同一原则。</li><li>\\(H\\) 与陈旧度是用收敛税买带宽的汇率，按两地小规模实验标定。</li><li>出处：McMahan 等，Communication-Efficient Learning of Deep Networks（FedAvg），2017；Douillard 等，DiLoCo，2023。</li></ul>',6))])}const _=s(n,[["render",d]]);export{f as __pageData,_ as default};
